SET NAMES utf8mb4;

INSERT INTO email_templates (id,name,purpose,subject,body_html,body_text,allowed_placeholders,trigger_description,is_active)
VALUES (
  '000',
  'Πρώτη απάντηση όταν δεν υπάρχουν αρκετές πληροφορίες',
  'Να ξεκινήσει η συζήτηση και να συλλεχθούν οι απαραίτητες πληροφορίες.',
  'Σας ευχαριστώ πολύ για το μήνυμά σας',
  '<p>Καλησπέρα σας {{couple_names}},</p><p>Σας ευχαριστώ πολύ για το μήνυμά σας και για το ενδιαφέρον σας σχετικά με τη φωτογράφιση του γάμου σας.</p><p>Με χαρά σας ενημερώνω πως η ημερομηνία σας είναι διαθέσιμη.</p><p>Πριν ετοιμάσω την πρότασή μου, θα ήθελα να μάθω λίγα περισσότερα για την ημέρα σας.</p><p>Θα μου ήταν πολύ χρήσιμο να μου γράψετε:</p><ul><li>Πού θα πραγματοποιηθεί το μυστήριο;</li><li>Πού θα γίνει η δεξίωση;</li><li>Περίπου πόσοι καλεσμένοι θα βρίσκονται μαζί σας;</li><li>Υπάρχει ήδη κάποιο πρόγραμμα ή κάποια ιδιαίτερη σκέψη που έχετε για την ημέρα σας;</li></ul><p>Εάν σας εξυπηρετεί περισσότερο, μπορούμε να κανονίσουμε μία σύντομη τηλεφωνική ή online συνάντηση ώστε να γνωριστούμε καλύτερα και να συζητήσουμε όλες τις λεπτομέρειες.</p><p>Μόλις έχω αυτές τις πληροφορίες, θα ετοιμάσω μία ολοκληρωμένη πρόταση ειδικά για εσάς.</p><p>Με εκτίμηση,<br>Βασίλης Μούμκας</p>',
  'Καλησπέρα σας {{couple_names}},\n\nΣας ευχαριστώ πολύ για το μήνυμά σας και για το ενδιαφέρον σας σχετικά με τη φωτογράφιση του γάμου σας.\n\nΜε χαρά σας ενημερώνω πως η ημερομηνία σας είναι διαθέσιμη.\n\nΠριν ετοιμάσω την πρότασή μου, θα ήθελα να μάθω λίγα περισσότερα για την ημέρα σας.\n\nΘα μου ήταν πολύ χρήσιμο να μου γράψετε:\n• Πού θα πραγματοποιηθεί το μυστήριο;\n• Πού θα γίνει η δεξίωση;\n• Περίπου πόσοι καλεσμένοι θα βρίσκονται μαζί σας;\n• Υπάρχει ήδη κάποιο πρόγραμμα ή κάποια ιδιαίτερη σκέψη που έχετε για την ημέρα σας;\n\nΕάν σας εξυπηρετεί περισσότερο, μπορούμε να κανονίσουμε μία σύντομη τηλεφωνική ή online συνάντηση.\n\nΜόλις έχω αυτές τις πληροφορίες, θα ετοιμάσω μία ολοκληρωμένη πρόταση ειδικά για εσάς.\n\nΜε εκτίμηση,\nΒασίλης Μούμκας',
  JSON_ARRAY('couple_names'),
  'Lead has supplied only a date or a short message without the necessary wedding details.',
  1
)
ON DUPLICATE KEY UPDATE name=VALUES(name),purpose=VALUES(purpose),subject=VALUES(subject),body_html=VALUES(body_html),body_text=VALUES(body_text),allowed_placeholders=VALUES(allowed_placeholders),trigger_description=VALUES(trigger_description),is_active=VALUES(is_active),version=version+1;
